# Generated by build.py from recipe.yml for recipe sftp-keep-a-pinned-host-key-across-restarts. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site rekeyed
printf '%s\n' 'hello from surl' > site/hello.txt
printf '%s\n' 'hello from surl' > rekeyed/hello.txt
cat > pin.sh <<'EOF'
#!/bin/sh
# Usage: sh pin.sh KEY.pub > pin.cfg
fingerprint=$(ssh-keygen -l -f "$1" | cut -d' ' -f2 | sed 's/^SHA256://')
printf 'hostpubsha256 = "%s"\n' "$fingerprint"
EOF
ssh-keygen -q -t rsa -b 3072 -N "" -f host_key
ssh-keygen -q -t rsa -b 3072 -N "" -f other_key
sh pin.sh host_key.pub > pin.cfg
surl -v --directory site --log-file main.log --hostkey host_key --user alice:s3cret sftp://127.0.0.1:8080/ &
sleep 1
curl -sS -K pin.cfg -u alice:s3cret sftp://127.0.0.1:8080/hello.txt
kill $(jobs -p)
